pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        amount = bound(amount, 2, type(uint256).max / 2);
        vm.assume(actor != address(c) && actor != address(this));

        // fund c through its receive()
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool sent, ) = address(c).call{value: amount}("");
        assertTrue(sent);
        assertEq(address(c).balance, amount);

        // owner (deployer == this) withdraws
        vm.prank(address(this));
        bool ok;
        try c.withdraw() { ok = true; } catch { ok = false; }

        // GENERAL RULE: a successful owner withdraw drains the FULL balance
        assertTrue(ok && address(c).balance == 0);
    }
}

