pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address target) public {
        vm.assume(amount > 0 && amount <= address(this).balance + 1e30);
        vm.assume(target != address(c));
        vm.deal(address(this), amount);

        uint256 before = address(c).balance;
        vm.prank(address(this)); // deployer is Owner
        c.Command{value: amount}(target, "");

        // Rule: Command forwards the attached value to the target, so c's
        // balance returns to its pre-call value (the attached value is not kept).
        assertTrue(address(c).balance == before);
    }
}

