pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seedBalance, uint256 amount, address actor, address recipient) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        vm.assume(recipient != address(c));
        vm.assume(recipient != address(0));
        seedBalance = bound(seedBalance, 1 ether, 1000 ether);
        amount = bound(amount, 1 wei, seedBalance - 1); // strictly below the threshold

        // give the contract a pre-existing balance greater than the incoming value
        vm.deal(address(this), seedBalance);
        (bool sent, ) = address(c).call{value: seedBalance}("");
        assertTrue(sent);
        require(address(c).balance == seedBalance);

        // actor calls multiplicate with msg.value < contract balance
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSelector(c.multiplicate.selector, recipient));
        assertTrue(ok);

        // GENERAL RULE: with msg.value < balance, multiplicate is a no-op;
        // the contract's balance must be unchanged.
        assertTrue(address(c).balance == seedBalance);
    }
}

