        // domain: contract pre-funded with `balance`, call value strictly below it
        balance = bound(balance, 1 ether, 1000 ether);
        amount = bound(amount, 1, balance - 1);
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(adr != address(0) && adr != address(c) && adr.code.length == 0);

        vm.deal(address(c), balance); // fund the reference contract
        vm.deal(actor, amount);

        vm.prank(actor);
        c.multiplicate(adr); // value = amount < balance: C must no-op

        // Rule: a multiplicate call whose value is below the contract's balance
        // must leave the contract's balance unchanged.
        assertTrue(address(c).balance == balance);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 balance, uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        balance = bound(balance, 1, type(uint96).max);
        // amount strictly below the contract's balance: in the reference this path is a no-op
        amount = bound(amount, 0, balance - 1);

        vm.deal(address(c), balance);

        // adversarial recipient that reverts on receiving ether
        Reverter adr = new Reverter();

        vm.deal(actor, amount);
        vm.prank(actor);
        try c.multiplicate{value: amount}(address(adr)) {
            // reference: no-op, succeeds; mutant: transfer to reverting recipient, reverts
            assertTrue(true);
        } catch {
            // the reference must never transfer in this state, so a revert is a violation
            assertTrue(address(c).balance < balance, "no-op path must not fail");
        }
    }
}

contract Reverter {
    receive() external payable { revert(); }
    fallback() external payable { revert(); }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(uint amt) public {
        require(amt > 0);
        require(address(this).balance >= amt);

        // fund c with amt by calling Command toward c itself with empty data (triggers receive)
        c.Command{value: amt}(address(c), new bytes(0));
        require(address(c).balance == amt);

        // non-owner calls withdraw via low-level call to capture revert boolean
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        assert(!ok && address(c).balance == amt);
    }

    receive() external payable {}
    fallback() external payable {}
}

